SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: 1.6(3)$q$, 'APPLICATION', $q$- This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: 1.6 Editor's note$q$, 'APPLICATION', $q$Editor’s note—The Building Act 1975 permits planning schemes to: - regulate, for the Building Code of Australia (BCA) or the Queensland Development Code (QDC), matters prescribed under a regulation under the Building Act 1975 (section 32).These include variations to provisions contained in parts MP1.1, MP1.2 and MP1.3 of the QDC such as heights of buildings related to obstruction and overshadowing, siting and design of buildings to provide visual privacy and adequate sight lines, on-site parking and outdoor living spaces. It may also regulate other matters, such as designating land liable to flooding, designating land as bushfire prone areas and transport noise corridors; - deal with an aspect of, or matter related or incidental to building work prescribed under a regulation under section 32 of the Building Act 1975; - specify alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33 of the Building Act 1975 Refer to Schedule 9 of the Regulation to determine assessable development, the type of assessment and any referrals applying to the building work.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, NULL);
