SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: Table 1.6.2 item 2$q$, 'APPLICATION', $q$2 | Schedule 9, Part 3, Division 2, Table 3, Item 1, Column 2(b) of the Regulation | If under the Building Act 1975, section 33, an alternative provision applies for the building work and, under the provision, the proposed building or structure is not of the quantifiable standard for a relevant qualitative statement under the provision, whether the proposed building or structure complies with the qualitative statement | The performance outcomes contained in Items 10, 11 and 12 of Table 1.6.1 |$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: Table 1.6.2 item 1$q$, 'APPLICATION', $q$1 | Schedule 9, Part 3, Division 2, Table 1 of the Regulation | Whether a single detached class 1(a)(i) building, class 1(a)(ii) building made up of not more than 2 attached dwellings or a class 10 building or structure will impact on the amenity or the aesthetics of the locality | Traditional building character (design) overlay code where the building work is in the traditional building character overlay | Dwelling house code or Dwelling house (small lot) code where the building work is in the following zones: - Rural zone - Rural residential zone - Environmental Management zone - Low density residential zone - Character residential zone and zone precincts - Low–medium density residential zone and zone precincts - Medium density residential zone - Emerging community zone - Township zone | The neighbourhood plan code relevant to the building work |$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: 1.7.4$q$, 'APPLICATION', $q$For the purpose of Schedule 9, Division 2 , Table 1 of the Regulation, building work for a building or structure which is a single detached class 1(a)(i) building, class 1(a)(ii) building comprising not more than 2 attached dwellings or a class 10 building or structure in a locality identified in Table 1.7.4 that does not comply with the acceptable outcomes in the codes identified in Table 1.7.4, is declared to: - have an extremely adverse effect on the amenity or likely amenity of the locality; or - be in extreme conflict with the character of the locality.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$QDC relationship: Dwelling house code AO2 editor's note$q$, 'APPLICATION', $q$Editor's note—This acceptable outcome is only for the maximum building height. Side boundary setbacks are provided in accordance with the Queensland Development Code; which vary according to the height of the building.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/162/0/false/28-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def setback$q$, 'DEFINITION', $q$Setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is. Editor’s note—Section 1.7.6 provides that for the purpose of determining compliance with assessment benchmarks for setback, development is deemed to comply with the assessment benchmarks if the development exceeds the assessment benchmarks only by reason of the inclusion of an outermost projection which is part of a building or structure that is: - an eave of a roof; or - a sunhood or the like attached to the wall of a building or structure to provide shade or shelter to the wall.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def site cover$q$, 'DEFINITION', $q$Site cover, of development, means the portion of the site, expressed as a percentage, that will be covered by a building or structure, measured to its outermost projection, after the development is carried out, other than a building or structure, or part of a building or structure, that is— - in a landscaped or open space area, including, for example, a gazebo or shade structure; or - a basement that is completely below ground level and used for car parking; or - the eaves of a building; or - a sun shade.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def building height$q$, 'DEFINITION', $q$Building height, of a building, means— - the vertical distance, measured in metres, between the ground level of the building and the highest point on the roof of the building, other than a point that is part of an aerial, chimney, flagpole or load-bearing antenna; or - the number of storeys in the building above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def domestic outbuilding$q$, 'DEFINITION', $q$Domestic outbuilding means a non-habitable class 10a building that is— - a shed, garage or carport; and - ancillary to a residential use carried out on the premises where the building is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def storey$q$, 'DEFINITION', $q$- means a space within a building between 2 floor levels, or a floor level and a ceiling or roof, other than— - a space containing only a lift shaft, stairway or meter room; or - a space containing only a bathroom, shower room, laundry, toilet or other sanitary compartment; or - a space containing only a combination of the things stated in subparagraph (i) or (ii); or - a basement with a ceiling that is not more than 1m above ground level; and - includes— - a mezzanine; and - a roofed structure that is on, or part of, a rooftop, if the structure does not only accommodate building plant and equipment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def small lot$q$, 'DEFINITION', $q$A lot which is: - less than 450m2; or - a rear lot of less than 600m2 excluding an access way.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def primary street frontage$q$, 'DEFINITION', $q$The street frontage that is most commonly addressed by other buildings in the block.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
