SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def rear lot$q$, 'DEFINITION', $q$A lot that has access to a road only by means of an access way that forms part of the lot, or by means of an easement over adjoining land.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def average width$q$, 'DEFINITION', $q$Average width, of a lot, means the distance, measured in metres, between the midpoint on each side boundary of the lot.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def boundary clearance$q$, 'DEFINITION', $q$Boundary clearance means the distance between a building or structure on premises and the boundary of the premises, measured from the part of the building or structure that is closest to the boundary, other than a part that is— - an architectural or ornamental attachment; or - a rainwater fitting.Examples — - If the fascia of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between the outside of the fascia and the boundary. - If a point on the roof of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between that point on the roof and the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def basement$q$, 'DEFINITION', $q$Basement means a space— - between a floor level in a building and the floor level that is immediately below it; and - no part of which is more than 1m above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def dwelling house$q$, 'DEFINITION', $q$Editor's note—The use term is defined in the Planning Regulation 2017 - Regulated Requirements Dwelling house means a residential use of premises involving— - 1 dwelling and any domestic outbuildings associated with the dwelling; or - 2 dwellings, 1 of which is a secondary dwelling, and any domestic outbuildings associated with either dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def secondary dwelling$q$, 'DEFINITION', $q$Secondary dwelling means a dwelling on a lot that is used in conjunction with, but subordinate to, another dwelling on the lot, whether or not the dwelling is— - attached to the other dwelling; or - occupied by individuals who are related to, or associated with, the household of the other dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def building envelope$q$, 'DEFINITION', $q$The three-dimensional extent of where a building and associated structure may be built on a site after consideration of limits set on height, setback and other similar measures.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def prescribed level$q$, 'DEFINITION', $q$The level of the surface of the land: - existing at the time the original estate was subdivided and roads created through the estate as determined by a registered surveyor under the Surveyors Act 2003 using best available evidence which is based on: - the ‘as constructed’ drawings for the subdivision of the original estate lodged with the Council; or - if paragraph (a)(i) does not apply, the 2002 contours of the Council’s mapping system; or - that is the result of operational work carried out as a consequence of a material change of use or reconfiguring a lot, if: - the material change of use or reconfiguring a lot was assessable development under the Council’s planning scheme in effect between 1 January 2002 and the commencement of this planning scheme; and - the operational work accords with the following: - the development approval for the material change of use or reconfiguring a lot; - the development approval which approved the operational work.Editor’s note—Section 1.7.5 provides that for the purpose of the definition of ground level in Schedule 1, the level of the natural ground is deemed to have been lawfully changed if the level of the natural ground level is the prescribed level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def minor road$q$, 'DEFINITION', $q$A road that is a neighbourhood road or local road.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def ground level$q$, 'DEFINITION', $q$Ground level means— - the level of the natural ground; or - if the level of the natural ground has changed, the level lawfully changed.Editor’s note—Section 1.7.5 provides that for the purpose of the definition of ground level in Schedule 1, the level of the natural ground is deemed to have been lawfully changed if the level of the natural ground level is the prescribed level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (SC1.1 use definitions / SC1.2 administrative terms) via ePlan glossary$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/rev/280/28-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$def built to boundary wall (code-specific)$q$, 'DEFINITION', $q$Note—Built to boundary walls are considered to be less than 900mm from the boundary for the purposes of this code.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Dwelling house (small lot) code AO25.1 note$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/163/0/false/28-Sep-2026/false$q$, NULL, NULL);
