SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$1.7.6$q$, 'OTHER', $q$- For the purpose of determining compliance with an assessment benchmark for setback, development is deemed to comply with the assessment benchmark if the development exceeds the assessment benchmark only by reason of the inclusion of an outermost projection which is part of a building or structure that is:
- an eave of a roof; or
- a sunhood or the like attached to the wall of a building or structure to provide shade or shelter to the wall.$q$, 'VERIFIED_VERBATIM', $q$rule 217 (section 1.7.6 heading rule 216)$q$, NULL, $q$Part 1 - Local government administrative matters$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/278/0/false/28-Sep-2026/false$q$, NULL, $q$deemed_compliance_eaves_sunhoods$q$);
SELECT define_rule($q${"rule_id": "BCC.deemed_compliance_eaves_sunhoods", "instrument_version": "BCC_CITY_PLAN_2014@2026-09-18", "topic": "OTHER", "title": "1.7.6", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "- For the purpose of determining compliance with an assessment benchmark for setback, development is deemed to comply with the assessment benchmark if the development exceeds the assessment benchmark only by reason of the inclusion of an outermost projection which is part of a building or structure that is:\n- an eave of a roof; or\n- a sunhood or the like attached to the wall of a building or structure to provide shade or shelter to the wall.", "extracted_value": ["eave of a roof", "sunhood or the like"], "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-18", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BRISBANE"}], "subjects": ["ANY"], "sources": [{"key": "deemed_compliance_eaves_sunhoods", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"setback_exclusions\", \"operator\": \"=\", \"value\": [\"eave of a roof\", \"sunhood or the like\"], \"unit\": null, \"conditions\": [\"applies to assessment benchmarks for setback\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'all buildings and structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Section heading: 'Deemed compliance with site cover and setback assessment benchmarks' but the text only addresses setback."}$q$::jsonb);
