SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$5.3.4 Table 5.3.4.1 (Building work, Traditional building character overlay / Pre-1911 building overlay)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$|  | Building work if in the Traditional building character overlay or the Pre-1911 building overlay, where not in the Local heritage place sub-category or the State heritage place sub-category of the Heritage overlay. | If for a dual occupancy, dwelling house or multiple dwelling, involving one or more of the following:
- an enclosed extension under an existing building to the extent of the core of the building along the front and side boundaries, other than a dwelling in the Local character significance sub-category;
- an enclosed extension at the rear where preceded by lawful demolition as either accepted development or approved in accordance with the Traditional building character (demolition) code;
- an external stair, ramp or lift;
- internal building work;
- a carport, garage, shed or other outbuilding at the rear of the building;
- a carport:
- if located:
- between the building and side boundary; or
- between the building and front boundary, where a maximum total width of 6m or 50% of the average width of the lot, excluding eaves, whichever is the lesser;
- if not in the Sherwood—Graceville district neighbourhood plan area or the Local character significance sub-category of the Traditional building character overlay;
- if associated with a dwelling house in the West End estate precinct of the West End—Woolloongabba district neighbourhood plan, where also complying with the requirements in AO13.2, AO13.3 and AO13.4 in that neighbourhood plan code;
- if associated with a multiple dwelling in the Hillside character precinct of the Ithaca district neighbourhood plan, where also complying with the requirements in AO23.3 in that neighbourhood plan code;
- decks, verandahs, balconies and other shade structures at the rear of the building;
- an in-ground swimming pool and/or spa (of any size) and unenclosed ancillary shade structures (where not at the rear, any shade structures are to have a maximum roofed area 10m2 and maximum height 3m)
Note—Where on a lot with more than one frontage, the rear of the building is that part of the site that is behind the building relative to the primary street frontage. |$q$, 'VERIFIED_VERBATIM', $q$rule 4718$q$, NULL, $q$Part 5 Table 5.3.4.1 Prescribed accepted development$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/222/0/false/28-Sep-2026/false$q$, NULL, $q$pad_tbc_outbuildings_carports_pools$q$);
SELECT define_rule($q${"rule_id": "BCC.pad_tbc_outbuildings_carports_pools", "instrument_version": "BCC_CITY_PLAN_2014@2026-09-18", "topic": "GARAGE.FRONTAGE", "title": "5.3.4 Table 5.3.4.1 (Building work, Traditional building character overlay / Pre-1911 building overlay)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "|  | Building work if in the Traditional building character overlay or the Pre-1911 building overlay, where not in the Local heritage place sub-category or the State heritage place sub-category of the Heritage overlay. | If for a dual occupancy, dwelling house or multiple dwelling, involving one or more of the following:\n- an enclosed extension under an existing building to the extent of the core of the building along the front and side boundaries, other than a dwelling in the Local character significance sub-category;\n- an enclosed extension at the rear where preceded by lawful demolition as either accepted development or approved in accordance with the Traditional building character (demolition) code;\n- an external stair, ramp or lift;\n- internal building work;\n- a carport, garage, shed or other outbuilding at the rear of the building;\n- a carport:\n- if located:\n- between the building and side boundary; or\n- between the building and front boundary, where a maximum total width of 6m or 50% of the average width of the lot, excluding eaves, whichever is the lesser;\n- if not in the Sherwood—Graceville district neighbourhood plan area or the Local character significance sub-category of the Traditional building character overlay;\n- if associated with a dwelling house in the West End estate precinct of the West End—Woolloongabba district neighbourhood plan, where also complying with the requirements in AO13.2, AO13.3 and AO13.4 in that neighbourhood plan code;\n- if associated with a multiple dwelling in the Hillside character precinct of the Ithaca district neighbourhood plan, where also complying with the requirements in AO23.3 in that neighbourhood plan code;\n- decks, verandahs, balconies and other shade structures at the rear of the building;\n- an in-ground swimming pool and/or spa (of any size) and unenclosed ancillary shade structures (where not at the rear, any shade structures are to have a maximum roofed area 10m2 and maximum height 3m)\nNote—Where on a lot with more than one frontage, the rear of the building is that part of the site that is behind the building relative to the primary street frontage. |", "extracted_value": null, "extracted_operator": "conditional"}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-18", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BRISBANE"}, {"level": "OVERLAY", "overlay": "BCC:OV:TRADITIONAL_BUILDING_CHARACTER_OVERLAY"}, {"level": "OVERLAY", "overlay": "BCC:OV:TRADITIONAL_BUILDING_CHARACTER_OVERLAY_PRE_1911_BUILDING_OVERLAY"}, {"level": "OVERLAY", "overlay": "BCC:OV:TRADITIONAL_BUILDING_CHARACTER_OVERLAY_PRE_1911_BUILDING_OVERLAY"}], "subjects": ["POOL", "CLASS_10A", "OUTDOOR_STRUCTURE"], "sources": [{"key": "pad_tbc_outbuildings_carports_pools", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"prescribed_accepted_tbc_minor_works\", \"operator\": \"conditional\", \"value\": null, \"unit\": null, \"conditions\": [\"outbuildings at the rear of the building\", \"carport between building and front boundary: max total width lesser of 6m or 50% of average lot width excl. eaves\", \"not in Sherwood-Graceville NP area or Local character significance sub-category (carport)\", \"in-ground pool/spa any size; non-rear shade structures max 10m2 and 3m high\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): not in Local or State heritage place sub-category of Heritage overlay\nStructure scope 'carport, garage, shed or other outbuilding at rear; carports beside/forward of building; rear decks/verandahs/shade structures; in-ground pools/spas' mapped by keyword to ['POOL', 'CLASS_10A', 'OUTDOOR_STRUCTURE']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Planning category only; QDC/QHC siting still applies for building assessment."}$q$::jsonb);
