INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$BCC.np_sherwood_westside_side_setback@2026-09-18$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$7.2.19.3.3 Table 7.2.19.3.3.A, PO1/AO1.1-AO1.2$q$, 'ACCEPTABLE_OUTCOME', $q$For accepted development subject to compliance with identified requirements (acceptable outcomes only) or assessable development |
If for a dwelling house: |
AO1.1
Development has:
- a maximum building footprint of 50% of the site area;
- a minimum area of private open space of 100m2, or 30% of the site, whichever is the greater, and has a minimum dimension of 3m. | AO1.2
Development has a minimum rear boundary setback of 6m.$q$, 'VERIFIED_VERBATIM', $q$rules 12201-12203$q$, NULL, $q$Sherwood—Graceville district neighbourhood plan code$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/113/0/false/28-Sep-2026/false$q$, NULL, $q$np_sherwood_dwelling_footprint$q$);
SELECT define_rule($q${"rule_id": "BCC.np_sherwood_dwelling_footprint", "instrument_version": "BCC_CITY_PLAN_2014@2026-09-18", "topic": "SITE_COVER", "title": "7.2.19.3.3 Table 7.2.19.3.3.A, PO1/AO1.1-AO1.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 50, "unit": "%", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-18", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BRISBANE"}, {"level": "LOCAL_PLAN", "local_plan": "BCC:NP_SHERWOOD_GRACEVILLE"}], "subjects": ["CLASS_1"], "sources": [{"key": "np_sherwood_dwelling_footprint", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_footprint\", \"operator\": \"<=\", \"value\": 50, \"unit\": \"%\", \"conditions\": [\"private open space min greater of 100m2 or 30% of site, min dimension 3m\", \"min rear boundary setback 6m (AO1.2)\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Sherwood—Graceville district neighbourhood plan\nStructure scope 'dwelling house' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Table 1.6.1 (only PO3/AO3.3-AO3.5 of this NP are). Heading: 'For accepted development subject to compliance with identified requirements (acceptable outcomes only) or assessable development' / 'If for a dwelling house:'. 'Building footprint' rather than 'site cover'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$BCC.np_sherwood_dwelling_footprint@2026-09-18$q$;
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$6.2.1.4 (4)(d) (Development location and uses overall outcomes)$q$, 'OTHER', $q$Development for a new dwelling house or dual occupancy is not accommodated.$q$, 'VERIFIED_VERBATIM', $q$rule 22134 (section 6.2.1.4, heading rule 703)$q$, NULL, $q$High density residential zone code$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/24/0/false/28-Sep-2026/false$q$, NULL, $q$bcc_hdr_zone_new_dwelling_house_not_accommodated$q$);
SELECT define_rule($q${"rule_id": "BCC.bcc_hdr_zone_new_dwelling_house_not_accommodated", "instrument_version": "BCC_CITY_PLAN_2014@2026-09-18", "topic": "OTHER", "title": "6.2.1.4 (4)(d) (Development location and uses overall outcomes)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "Development for a new dwelling house or dual occupancy is not accommodated.", "extracted_value": null, "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-18", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BRISBANE"}, {"level": "ZONE", "zone": "BCC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "bcc_hdr_zone_new_dwelling_house_not_accommodated", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"new_dwelling_house_supported_in_zone\", \"operator\": \"=\", \"value\": null, \"unit\": null, \"conditions\": [\"overall outcome: a new dwelling house is not accommodated in the zone (both Up to 8 storeys and Up to 15 storeys zone precincts)\", \"new dwelling house MCU is impact assessable (Table 5.5.4 'Any use listed in this table and not meeting the description'; Table 5.10.9 Dwelling house character overlay row 13134); this overall outcome is an assessment benchmark (the applicable zone code)\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): any lot size (no lot-size condition)\nStructure scope 'new dwelling house (material change of use); does not address extensions or domestic outbuildings' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: The HDR zone code (6.2.1.4) contains only purpose and overall outcomes - no performance/acceptable outcome table and no numeric siting standard for a dwelling house, domestic outbuilding or pool. Building height in the zone is set for multiple dwellings (Table 5.5.4 / Multiple dwelling code: 8 storeys in the Up to 8 storeys zone precinct, 15 storeys in the Up to 15 storeys zone precinct), not for dwelling houses. Related overall outcome 6.2.1.4(4)(e): 'Development is not required to be responsive to or to provide a sensitive transition to a lower density building, including a dwelling house on an adjoining site within the High density residential zone ...'. Siting-relevant only as a flag: a new dwelling house in HDR needs an impact assessable DA and conflicts with the zone intent."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$BCC.bcc_hdr_zone_new_dwelling_house_not_accommodated@2026-09-18$q$;
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$5.3.4 Table 5.3.4.1 (Building work, Dwelling house character overlay, small lot, outside building envelope - raising only)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$|  | Building work if in the Dwelling house character overlay and on a small lot where:
- outside the building envelope contained in the acceptable outcomes in section A or section B of the Dwelling house (small lot) code; or
- outside the building envelope contained in a development approval to the extent it differs from (a) above. | If for a dwelling house involving only raising a building where:
- the side boundary setbacks comply with the setbacks under the Building Regulation 2021;
- the maximum height does not exceed 9.5m above ground level; or
- the maximum height does not exceed 11.5m above ground level where within the 3 or 4 storey mix zone precinct of the Low-medium density residential zone;
- any windows that are within 2m at ground level or 9m above ground level of a neighbouring dwelling house (refer to Figure g in the Dwelling house (small lot) code):
- are offset from the window of a habitable room in the adjacent dwelling house to limit direct outlook as shown in Figure h in the Dwelling house (small lot) code; or
- have sill heights of 1.5m above floor level; or
- are covered by fixed obscure glazing in any part of the window below 1.5m above floor level; or
- have fixed external screens; or
- in the case of screening for a ground floor level, fencing to a height of 1.5m above ground floor level;
- any screening devices required above, are:
- solid translucent screens, perforated or slatted panels or fixed louvres that have a maximum of 25% openings, with a maximum opening dimension of 50mm, that are permanently fixed and durable (refer to Figure j and Figure i in the Dwelling house (small lot) code);
- offset a minimum of 0.3m from the face of any window;
- may be hinged to facilitate emergency egress only.
Note—For the purpose of this provision the setbacks of the Building Regulation 2021 are to be read as taken to the wall, not the outermost projection.
Note—Unless specified, the above building works are still subject to the siting provisions of the Building Regulation 2021. |$q$, 'VERIFIED_VERBATIM', $q$rule 4588$q$, NULL, $q$Part 5 Table 5.3.4.1 Prescribed accepted development$q$, NULL, $q$https://cityplan.brisbane.qld.gov.au/eplan/api/l/r/222/0/false/28-Sep-2026/false$q$, $q$Height measured above ground level (SC1.2 building height). Setbacks under the Building Regulation 2021 are 'to be read as taken to the wall, not the outermost projection' for this provision.$q$, $q$bcc_hdr_pad_dhc_small_lot_raising_height$q$);
SELECT define_rule($q${"rule_id": "BCC.bcc_hdr_pad_dhc_small_lot_raising_height", "instrument_version": "BCC_CITY_PLAN_2014@2026-09-18", "topic": "HEIGHT.BUILDING", "title": "5.3.4 Table 5.3.4.1 (Building work, Dwelling house character overlay, small lot, outside building envelope - raising only)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9.5, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-18", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "BRISBANE"}, {"level": "ZONE", "zone": "BCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "OVERLAY", "overlay": "BCC:OV:DWELLING_HOUSE_CHARACTER_OVERLAY"}], "subjects": ["CLASS_1"], "sources": [{"key": "bcc_hdr_pad_dhc_small_lot_raising_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": 9.5, \"unit\": \"m\", \"conditions\": [\"only for raising an existing dwelling house on a small lot in the Dwelling house character overlay (all HDR land)\", \"side boundary setbacks comply with the setbacks under the Building Regulation 2021 (QDC/QHC), read as taken to the wall, not the outermost projection\", \"windows within 2m at ground level or 9m above ground level of a neighbouring dwelling house: offset, 1.5m sill height, obscure glazing below 1.5m, fixed external screens, or 1.5m fencing for ground floor\", \"screens max 25% openings, max opening dimension 50mm, offset min 0.3m from window\"], \"exceptions\": [\"11.5m limit applies only in the 3 or 4 storey mix zone precinct of the Low-medium density residential zone - not in HDR\"], \"formula_text\": null}\nLot conditions (not encoded): small lot (lot < 450 m2, or rear lot < 600 m2 excl. access way); building work outside the building envelope in the acceptable outcomes of section A or B of the Dwelling house (small lot) code (or outside an approved envelope)\nStructure scope 'existing dwelling house - raising a building only' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Prescribed accepted development (not assessable under the scheme) - not an alternative provision. Row is not zone-limited; it applies in every zone covered by the Dwelling house character overlay (LDR, LMR, MDR, HDR, CR, Tourist accommodation). Not previously captured in brisbane.json (only rows 4587 and 4589 were). Table 5.5.4 note: 'the Dwelling house character overlay applies to all land within this zone'. If raising does not meet these requirements it falls back to Table 5.10.9 (building work for an extension -> Dwelling house (small lot) code)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$BCC.bcc_hdr_pad_dhc_small_lot_raising_height@2026-09-18$q$;
SELECT define_provision($q$BCC_CITY_PLAN_2014@2026-09-18$q$, $q$5.3.4 Table 5.3.4.1 (Building work, Dwelling house character overlay, small lot, outside building envelope - raising only)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$|  | Building work if in the Dwelling house character overlay and on a small lot where:
