INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$QHC transition: City Plan v37 Table 1.6.1 still refers to QDC MP1.1/MP1.2. Confirm under the QHC / Building Regulation 2021 transitional provisions how these alternative provisions map onto QHC Chapters 1 and 2 (and whether performance-criteria numbering P1-P9 is preserved). A secondary source says old provisions continue to apply to a scheme until an amending scheme or 1 Sept 2029 - not verified from primary text.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Standard (non-small) lots: Brisbane provides no setback/site-cover alternative provisions in the Dwelling house code, so QHC Chapter 2 values govern Class 10a siting unless an NP provision listed in Table 1.6.1 or TBC overlay AO1.2/AO2.1 applies. Each NP listed in Table 1.6.1 (15+ codes) should be extracted individually if those areas are in scope.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Table 1.6.1 item 9 references 'Bushfire overlay code PO21 and AO21.2' but the current Bushfire overlay code (8.2.5) only runs to PO20/AO20.2 - stale cross-reference.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Dwelling house (small lot) code AO5(c) garage 5.5m setback mentions 'garages' only; whether carports are captured needs certifier/Council interpretation (Section B AO22.2 uses 'covered car parking').$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Small lot AO7 'average depth' is not defined in SC1.2 (only 'average width' is).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Small lot setbacks apply to 'development' with no Class 10a concessions (e.g. AO7 rear 3m/6m); confirm Council practice for sheds/carports in rear setback of small lots (likely concurrence referral under Table 1.6.2).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Swimming pools: City Plan contains no pool boundary setback provision; pools appear only in prescribed accepted development (Table 5.3.4.1) and as impervious area (small lot Section B AO20). Pool siting falls to QDC/QHC and pool safety laws.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Package W schedule (v37) text for Table 5.5.2 includes a note that 'All dwelling houses in the Low-medium density residential zone may become assessable development as the Dwelling house character overlay applies to all land within this zone' - this note was not present in the live ePlan Table 5.5.2 text retrieved; reconcile.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Dwelling house character overlay mapping extent per lot needs the overlay map (GIS) - not extracted.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$HEIGHT GAP: neither the Dwelling house code (AO2 / AO3) nor Section A of the Dwelling house (small lot) code (AO3 / AO4) names the High density residential zone, so there is NO acceptable-outcome height for a dwelling house in HDR on a lot of 180 m2 or more. The '9.5 m' assumption for standard lots does not hold in HDR. For accepted-subject-to-requirements extensions there is no scheme height AO to meet (QDC/QHC height-dependent setbacks still apply); for assessable development only the performance outcomes (DH code PO2/PO3; small lot code PO3/PO4) could be used, and their zone scope is not stated. Section A AO2 (building envelope) refers to 'the acceptable outcome for maximum building height', which does not exist for HDR. Exceptions: lots < 180 m2 (Section B AO18: 11.5 m and 3 storeys, not zone-limited) and raising on a small lot under Table 5.3.4.1 row 4588 (9.5 m). Needs manual review / Council confirmation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Existing brisbane.json records whose text applies in HDR (dh_parking_spaces, dh_secondary_dwelling_size, dh_building_envelope_plan, all sl_* except sl_max_height_low_density, sl_max_height_lmr_3_4_storey_mdr and sl_built_to_boundary_character_precinct, and all slb_*) have zones arrays that omit 'High density residential zone'. Recommend adding HDR to those arrays rather than duplicating records. NOT applicable in HDR: dh_max_height_low_density, dh_max_height_lmr_3_4_storey_mdr, dh_ridgeline_height, sl_max_height_low_density, sl_max_height_lmr_3_4_storey_mdr, sl_built_to_boundary_character_precinct, the AO6(c)(iv) limb of sl_side_zero_setback, tbc_* (TBC overlay not applied to dwelling houses in HDR; Pre-1911 overlay aside), np_* (the New Farm / Sherwood precincts named are not HDR).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Standard lots (>= 450 m2 and not a rear lot < 600 m2) in HDR: the Dwelling house code has no setback or site-cover AO, so Class 10a siting (setbacks, site cover) and pool siting fall to QDC MP1.1/MP1.2 (now QHC) through the Building Regulation 2021. The only scheme numbers are AO1.2 (secondary dwelling max 80 m2 GFA, within 20 m), AO4 (1 parking space) and AO7 (approved envelope).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Is a detached Class 10a outbuilding (shed/garage/carport) or a swimming pool on a non-small HDR lot 'Building work for an extension to a dwelling house' under Table 5.10.9? If not, it is not listed in Table 5.10.9 or Table 5.7.1 and is accepted development by default (s5.3.2 rule 21880), subject only to Building Regulation siting. On small lots, Table 5.3.4.1 row 4589 makes 1 shed (10 m2, 3 m), carports and pools prescribed accepted; other work outside the envelope falls back to Table 5.10.9 (small lot code). Needs Council/certifier confirmation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Does the Dwelling house character overlay really cover every HDR lot? The Table 5.5.4 note says it 'applies to all land within this zone'; the overlay map (Schedule 2) was not checked lot by lot. If a lot were outside the overlay, Table 5.5.4 alone applies (MCU impact; building work accepted by default).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$QHC transition: Table 1.6.1 still cites QDC MP1.1/MP1.2 (same issue as in brisbane.json). Dwelling house (small lot) code PO6/AO6 (incl. the HDR 15 m non-habitable length) is listed in Table 1.6.1 item 11 as an alternative provision; Dwelling house code PO7/AO7 in items 6, 10 and 11; PO4/AO4 in item 8.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Neighbourhood plans that include HDR land (e.g. inner-city NPs) may set dwelling-house siting numbers or change the category of assessment (section 5.9); none were extracted here. Table 1.6.1 item 6 lists NP codes (e.g. Spring Hill PO1/AO1 and PO7/AO7.2; West End-Woolloongabba PO1/AO1 and PO6/AO6.1-AO6.2; Fortitude Valley PO1/AO1.2) that may cover HDR land.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$BRISBANE$q$, $q$BCC_CITY_PLAN_2014$q$, 'MEDIUM', $q$Heritage, Pre-1911 building, flood and other overlays can still raise the level of assessment in HDR (section 5.10); not extracted here.$q$);
